script:
(function () {
  'use strict';
  // Retirement with part-time earnings, compared with the same retirement without work.
  //   Year k (age = retirement age + k, year 1 = 2026):
  //     spending = first-year spending x (1 + inflation)^k
  //     pay      = part-time earnings (x (1 + inflation)^k if ticked) for the chosen number of years
  //     benefit  = monthly benefit x 12 x (1 + inflation)^k from the claiming age
  //     earnings test (only with pay, before full retirement age):
  //       12 months before full retirement age: withheld = (pay - higher limit) / 3
  //       earlier years:                       withheld = (pay - annual limit) / 2
  //       never more than the year's benefit; limits rise with inflation after 2026
  //     draw = spending - pay - (benefit - withheld), taken at the start of the year (a negative
  //       draw is saved); balance = (balance - draw) x (1 + return)
  //   Savings last until the age when a draw first exceeds the balance (fractional final year).
  // Checked in Node (scratch tests): 0% return and inflation, $600,000, $60,000 spending -> lasts
  //   10 years without work; $30,000 pay for 5 years -> $150,000 less drawn -> 12.5 years. Earnings
  //   test: $30,000 at 62 with $1,800/month -> ($30,000 - $24,480) / 2 = $2,760 withheld; $80,000 in
  //   the year before full retirement age -> ($80,000 - $65,160) / 3 = $4,946.67; $100,000 at 62
  //   -> capped at the $21,600 yearly benefit; no withholding at or after full retirement age.
  //
  // ---- Social Security retirement earnings test (2026) -----------------------------------
  // Annual exempt amounts for 2026: $24,480 under full retirement age ($1 withheld for every $2
  //   above), $65,160 in the year you reach full retirement age ($1 for every $3 above, counting
  //   earnings before the month you reach it). Source: SSA, "Exempt Amounts Under the Earnings
  //   Test" (ssa.gov/oact/cola/rtea.html) and "How Work Affects Your Benefits" 2026 (EN-05-10069).
  // Full retirement age: 66 for 1943-1954 births, rising 2 months a year to 67 for 1960 and later.
  var LIMIT_UNDER_FRA = 24480, LIMIT_FRA_YEAR = 65160;
  // ---------------------------------------------------------------------------------------

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return isFinite(x) ? moneyFmt.format(Math.abs(x) < 0.5 ? 0 : x) : '–'; } };
  var one = new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 });

  function withheldFor(age, pay, benefit, fra, scale) {
    if (benefit <= 0 || pay <= 0 || age >= fra) return 0;
    var w = age === fra - 1 ? Math.max(0, pay - LIMIT_FRA_YEAR * scale) / 3 : Math.max(0, pay - LIMIT_UNDER_FRA * scale) / 2;
    return Math.min(w, benefit);
  }

  // p: age, planAge, savings, spend, earn, workYears, ss (monthly), claim, ret, inflation (decimals),
  // fra, test (bool), earnInfl (bool); work = true runs the scenario with part-time pay
  function simulate(p, work) {
    var b = p.savings, rows = [], lasts = null, totalEarn = 0, totalHeld = 0;
    for (var k = 0; p.age + k < p.planAge; k++) {
      var age = p.age + k, infl = Math.pow(1 + p.inflation, k);
      var spend = p.spend * infl;
      var pay = work && k < p.workYears ? p.earn * (p.earnInfl ? infl : 1) : 0;
      var benefit = age >= p.claim ? p.ss * 12 * infl : 0;
      var held = p.test ? withheldFor(age, pay, benefit, p.fra, infl) : 0;
      var draw = spend - pay - (benefit - held);
      var out = false;
      if (draw > b + 1e-9) {
        if (lasts === null) lasts = k + (draw > 0 ? Math.max(0, b) / draw : 0);
        draw = b; out = true;
      }
      b = (b - draw) * (1 + p.ret);
      totalEarn += pay; totalHeld += held;
      rows.push({ age: age, pay: pay, paid: benefit - held, held: held, spend: spend, draw: draw, balance: b, out: out });
    }
    return { rows: rows, lasts: lasts, end: b, totalEarn: totalEarn, totalHeld: totalHeld };
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function checked(id) { var el = document.getElementById(id); return !!(el && el.checked); }
  function signed(x) { return x < -0.5 ? '-' + money.format(-x) : money.format(x); }

  function update() {
    var age = Math.round(num('reAge')), planAge = Math.round(num('rePlanAge')), savings = num('reSavings'), spend = num('reSpend'),
        earn = num('reEarn'), workYears = Math.round(num('reWorkYears')), ss = num('reSs'), claim = Math.round(num('reClaim')),
        ret = num('reReturn'), inflation = num('reInflation'), fra = parseInt(document.getElementById('reFra').value, 10);
    var error = document.getElementById('reError');
    var bad = [age, planAge, savings, spend, earn, workYears, ss, claim, ret, inflation, fra].some(isNaN) ||
              age < 50 || age > 80 || planAge <= age || planAge > 110 || savings < 0 || spend < 0 || earn < 0 ||
              workYears < 0 || workYears > 30 || ss < 0 || claim < 62 || claim > 70 || ret < 0 || ret > 30 ||
              inflation < 0 || inflation > 20;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Use a retirement age from 50 to 80, a plan age above it (up to 110), a claiming age from 62 to 70, ' +
                          '0 to 30 years of work, non-negative amounts, a return up to 30% and inflation up to 20%.';
      return;
    }
    var p = { age: age, planAge: planAge, savings: savings, spend: spend, earn: earn, workYears: workYears, ss: ss, claim: claim,
              ret: ret / 100, inflation: inflation / 100, fra: fra, test: checked('reTest'), earnInfl: checked('reEarnInfl') };
    var w = simulate(p, true), n = simulate(p, false);
    function lastsText(x) { return x.lasts === null ? 'Past age ' + planAge : 'To age ' + one.format(age + x.lasts); }
    set('reLastsWork', lastsText(w));
    set('reLastsNo', lastsText(n));
    if (n.lasts === null) {
      set('reEndDiffLabel', 'Extra savings at age ' + planAge);
      set('reEndDiff', money.format(w.end - n.end));
    } else {
      var extra = (w.lasts === null ? planAge - age : w.lasts) - n.lasts;
      set('reEndDiffLabel', 'Extra years your savings last');
      set('reEndDiff', (w.lasts === null ? 'At least ' : '') + (extra > 0.05 ? '+' : '') + one.format(extra) + ' years');
    }
    set('reTotalEarn', money.format(w.totalEarn));
    set('reTotalHeld', money.format(w.totalHeld));
    set('reEndWorkLabel', 'Balance at age ' + planAge + ', with work');
    set('reEndWork', money.format(w.end));
    set('reEndNoLabel', 'Balance at age ' + planAge + ', without work');
    set('reEndNo', money.format(n.end));
    set('reFirst', signed(w.rows[0].draw) + ' / ' + signed(n.rows[0].draw));

    var note;
    var first = w.rows.filter(function (x) { return x.held > 0; })[0];
    if (earn === 0 || workYears === 0) note = 'Enter part-time earnings and the years you plan to work to see how they stretch your savings.';
    else if (!p.test) note = 'The earnings test is switched off, so the full benefit is paid every year you work.';
    else if (claim >= fra) note = 'You claim at or after full retirement age, so the earnings test never withholds your benefits.';
    else if (first) note = 'At age ' + first.age + ' you earn ' + money.format(first.pay) + ', which is over the earnings limit, so SSA would withhold about ' +
      money.format(first.held) + ' of that year\'s benefits. In total ' + money.format(w.totalHeld) + ' is withheld while you work before full retirement age.';
    else note = 'Your part-time pay stays under the earnings test limits, so no benefits are withheld.';
    set('reTestNote', note);

    var body = document.getElementById('reSchedule');
    body.textContent = '';
    w.rows.forEach(function (x, i) {
      var tr = document.createElement('tr');
      [x.age, money.format(x.pay), money.format(x.paid), money.format(x.held), money.format(x.spend),
       signed(x.draw) + (x.out ? ' (runs out)' : ''), money.format(x.balance), money.format(n.rows[i].balance)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('reForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
